void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = fragCoord.xy / iResolution.xy * 2. - 1.;  // normalize
    p.x *= iResolution.x / iResolution.y;  // fix aspect-ratio

    float t = iTime * 2.5;
    float a = atan(p.y, p.x) *4.;
    float l = length(p);
    float i = sin(a+l*3. + t*.5) * sin(a+l*9. + t*.2);
 //   i = fract(i *(1. + sin(t)));

    // Cosine palette
    vec3 color = cos(6.2831853 * (i + vec3(.5, .32, .15))) * .5 + .5;
    i += sin(a+l*2.+t*1.3);
    vec3 colorB = cos(6.2831 * vec3(i*.4,i*.5,i*.6));
    color = mix(color, colorB, .5);
    fragColor = vec4(color, 1.);
}
